 <aside class="sidebar"><section class="side-panel"><div class="side-title"><h2>Tu once titular</h2><span class="counter">05 / 11</span></div><p class="sub">Toca un jugador para elegir a tu protagonista.</p><div class="players" id="players"></div><div class="squad-footer"><div class="team-power"><div><div>PODER DEL EQUIPO <span class="power-score">92</span></div><div class="power-dots"><i></i><i></i><i></i><i></i><i></i><i></i><i></i></div></div></div><button class="start-btn" id="sidePlay">A LA CANCHA&nbsp; ↗</button></div></section><section class="side-panel tip-panel"><div class="tip-label">✦ CONSEJO DEL DT</div><h3>El espacio es tuyo.</h3><p>Busca el arco, combina con tus compañeros y carga el tiro para vencer al portero. ¡Cada gol cuenta!</p></section></aside>
 </main><footer class="bottomline"><span>CANCHA DE LEYENDAS © 2025</span><span>HECHO PARA JUGAR • HECHO PARA GANAR</span></footer>
 </div>
 <script>
+const squad=[
+ {name:'Gilberto Mora',number:10,role:'Mediocampista',class:'p10',rating:94},
+ {name:'Cristiano Ronaldo',number:7,role:'Delantero',class:'p7',rating:96},
+ {name:'Lionel Andrés Messi',number:30,role:'Delantero',class:'p30',rating:98},
+ {name:'Erling Haaland',number:9,role:'Goleador',class:'p9',rating:95},
+ {name:'Neymar Jr.',number:11,role:'Extremo',class:'p11',rating:93},
+ {name:'Tú',number:8,role:'Mediocampista',class:'p8',rating:88},
+ {name:'Kylian Mbappé',number:4,role:'Delantero',class:'p4',rating:94},
+ {name:'Vinícius Jr.',number:2,role:'Extremo',class:'p2',rating:92}
+];
+let selected=0,playing=false,ended=false,home=0,away=0,timeLeft=90,playerObjs=[],ball={},lastTime=0,toastTimer=0,keys={};
+const canvas=document.getElementById('pitch'),ctx=canvas.getContext('2d'),arena=document.getElementById('arena');
+const $=id=>document.getElementById(id);
+function renderSquad(){ $('players').innerHTML=squad.map((p,i)=>`<div class="player-card ${i===selected?'selected':''}" data-index="${i}"><div class="portrait ${p.class}"><span>${p.number}</span></div><div class="player-info"><div class="player-name">${p.name}</div><div class="player-role">${p.role}</div></div><span class="jersey">${p.number}</span></div>`).join('');document.querySelectorAll('.player-card').forEach(el=>el.onclick=()=>{if(!playing){selected=+el.dataset.index;renderSquad();updateCaptain()}});updateCaptain()}
+function updateCaptain(){const p=squad[selected];$('captainName').textContent=p.name;$('miniAvatar').textContent=p.number}
+renderSquad();
+function resize(){const r=arena.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2);canvas.width=r.width*d;canvas.height=r.height*d;canvas.style.width=r.width+'px';canvas.style.height=r.height+'px';ctx.setTransform(canvas.width/1000,0,0,canvas.height/600,0,0);draw()}
+new ResizeObserver(resize).observe(arena);
+function makePlayers(){playerObjs=[];const positions=[[200,300],[330,190],[330,410],[440,290],[530,190],[530,410],[650,270],[770,300]];positions.forEach((v,i)=>playerObjs.push({x:v[0],y:v[1],bx:v[0],by:v[1],team:0,idx:i,vx:0,vy:0,number:squad[i%squad.length].number,selected:i===selected}));[[870,170],[835,300],[870,430],[710,150],[710,450],[575,300],[430,150],[430,450]].forEach((v,i)=>playerObjs.push({x:v[0],y:v[1],bx:v[0],by:v[1],team:1,idx:i,vx:0,vy:0,number:[9,7,10,11,8,6,4,2][i]}));ball={x:500,y:300,vx:0,vy:0};playerObjs[selected].x=470;playerObjs[selected].y=300;playerObjs[0].x=270;playerObjs[0].y=225;playerObjs[2].x=270;playerObjs[2].y=375}
+function drawPitch(){ctx.fillStyle='#19422c';ctx.fillRect(0,0,1000,600);for(let i=0;i<10;i++){ctx.fillStyle=i%2?'#205034':'#1b482f';ctx.fillRect(i*100,0,100,600)}ctx.strokeStyle='#d9efd3aa';ctx.lineWidth=2;ctx.strokeRect(38,38,924,524);ctx.beginPath();ctx.moveTo(500,38);ctx.lineTo(500,562);ctx.stroke();ctx.beginPath();ctx.arc(500,300,75,0,Math.PI*2);ctx.stroke();ctx.fillStyle='#d9efd3';ctx.beginPath();ctx.arc(500,300,3,0,Math.PI*2);ctx.fill();ctx.strokeRect(38,190,115,220);ctx.strokeRect(847,190,115,220);ctx.strokeRect(38,235,48,130);ctx.strokeRect(914,235,48,130);ctx.beginPath();ctx.arc(125,300,4,0,Math.PI*2);ctx.arc(875,300,4,0,Math.PI*2);ctx.fill();ctx.strokeRect(5,245,34,110);ctx.strokeRect(961,245,34,110);ctx.fillStyle='#fff3';ctx.fillRect(0,245,38,110);ctx.fillRect(962,245,38,110)}
+function drawPlayer(p){const isUser=p.team===0&&p.idx===selected;ctx.save();ctx.translate(p.x,p.y);ctx.fillStyle='#0005';ctx.beginPath();ctx.ellipse(0,13,13,5,0,0,Math.PI*2);ctx.fill();if(isUser){ctx.strokeStyle='#d8ff58';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,18,0,Math.PI*2);ctx.stroke()}ctx.fillStyle=p.team===0?'#e7e8d8':'#e94d48';ctx.beginPath();ctx.arc(0,0,13,0,Math.PI*2);ctx.fill();ctx.fillStyle=p.team===0?'#286ad2':'#f2eee0';ctx.beginPath();ctx.arc(0,-8,7.3,0,Math.PI*2);ctx.fill();ctx.fillStyle=p.team===0?'#17345d':'#612d2b';ctx.beginPath();ctx.arc(0,-10,7,Math.PI,Math.PI*2);ctx.fill();ctx.fillStyle=p.team===0?'#153b7d':'#a43536';ctx.font='bold 8px system-ui';ctx.textAlign='center';ctx.fillText(String(p.number),0,3);if(isUser){ctx.fillStyle='#d8ff58';ctx.beginPath();ctx.moveTo(-5,-24);ctx.lineTo(5,-24);ctx.lineTo(0,-19);ctx.fill()}ctx.restore()}
+function draw(){if(!ctx||!canvas.width)return;drawPitch();playerObjs.forEach(drawPlayer);if(ball){ctx.save();ctx.fillStyle='#0005';ctx.beginPath();ctx.ellipse(ball.x+2,ball.y+7,9,4,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#fff';ctx.beginPath();ctx.arc(ball.x,ball.y,8,0,Math.PI*2);ctx.fill();ctx.fillStyle='#243029';ctx.font='bold 9px system-ui';ctx.textAlign='center';ctx.fillText('⬟',ball.x,ball.y+3);ctx.restore()}}
+function setStatus(text){$('status').textContent=text}
+function kickoff(){makePlayers();playing=true;ended=false;timeLeft=90;lastTime=performance.now();$('overlay').classList.add('hidden');$('hint').textContent='WASD / FLECHAS para moverte · ESPACIO tiro · J pase';setStatus('¡RUEDA EL BALÓN!');$('clock').textContent='90:00';requestAnimationFrame(loop)}
+function finish(){playing=false;ended=true;const win=home>away;$('modalKicker').textContent=win?'¡PARTIDAZO!':'FIN DEL PARTIDO';$('modalTitle').innerHTML=win?'¡Victoria<br>de leyendas!':home===away?'¡Empate<br>de campeones!':'¡A por la<br>revancha!';$('modalText').textContent=`Marcador final: Leyendas ${home} — ${away} Rivales. ${win?'El estadio celebra tu jugada.':'La próxima será nuestra. ¡Inténtalo otra vez!'}`;$('playBtn').textContent='JUGAR OTRA VEZ  ↻';$('overlay').classList.remove('hidden');$('hint').textContent='Pulsa el botón para volver a jugar';setStatus('PARTIDO FINALIZADO')}
