function score(team){if(team===0)home++;else away++;$('homeScore').textContent=home;$('awayScore').textContent=away;announce(team===0?'¡GOOOL!':'GOL RIVAL');setStatus(team===0?'¡GOL DE LAS LEYENDAS!':'GOL DE LOS RIVALES');setTimeout(()=>{if(playing){makePlayers();setStatus('¡SIGUE EL PARTIDO!')}},1500)}
function doAction(type){if(!playing)return;const user=playerObjs.find(p=>p.team===0&&p.idx===selected);if(!user)return;let dx=ball.x-user.x,dy=ball.y-user.y,d=Math.hypot(dx,dy);if(type==='shoot'){if(d<62){const power=keys.space?710:610;ball.vx=power;ball.vy=(300-ball.y)*.65+(Math.random()-.5)*68;setStatus('¡TIRO A PUERTA!')}else{user.vx+=75;setStatus('¡ACÉRCATE AL BALÓN!')}}else{if(d<70){let mate=playerObjs.filter(p=>p.team===0&&p.idx!==selected).sort((a,b)=>Math.hypot(a.x-ball.x,a.y-ball.y)-Math.hypot(b.x-ball.x,b.y-ball.y))[0];if(mate){const m=Math.hypot(mate.x-ball.x,mate.y-ball.y)||1;ball.vx=(mate.x-ball.x)/m*390;ball.vy=(mate.y-ball.y)/m*390;setStatus('¡BUEN PASE!')}}else setStatus('¡SIGUE CORRIENDO!')}}
function loop(now){if(!playing)return;let dt=Math.min((now-lastTime)/1000,.04);lastTime=now;timeLeft=Math.max(0,timeLeft-dt);const secs=Math.ceil(timeLeft);$('clock').textContent=`${String(Math.floor(secs/60)).padStart(2,'0')}:${String(secs%60).padStart(2,'0')}`;if(timeLeft<=0){finish();draw();return}
 const user=playerObjs.find(p=>p.team===0&&p.idx===selected);if(user){let mx=(keys.ArrowRight||keys.d?1:0)-(keys.ArrowLeft||keys.a?1:0),my=(keys.ArrowDown||keys.s?1:0)-(keys.ArrowUp||keys.w?1:0),len=Math.hypot(mx,my)||1;user.vx=mx/len*245;user.vy=my/len*245;user.x=Math.max(45,Math.min(955,user.x+user.vx*dt));user.y=Math.max(48,Math.min(552,user.y+user.vy*dt));}
 // Teammates advance into space; rivals close down the ball and defend their goal.
 playerObjs.forEach(p=>{if(p.team===0&&p.idx!==selected){let tx=p.bx+(ball.x-500)*.23,ty=p.by+(ball.y-300)*.3;if(ball.x>p.x+95&&p.idx%2)tx+=35;let dx=tx-p.x,dy=ty-p.y,d=Math.hypot(dx,dy)||1;p.x+=dx/d*Math.min(d,72*dt);p.y+=dy/d*Math.min(d,72*dt)}else if(p.team===1){let isKeeper=p.idx===1,tx=isKeeper?Math.max(835,Math.min(883,ball.x)):Math.max(530,Math.min(860,ball.x-35)),ty=isKeeper?Math.max(250,Math.min(350,ball.y)):ball.y+(p.idx%2?24:-24);let dx=tx-p.x,dy=ty-p.y,d=Math.hypot(dx,dy)||1;let speed=isKeeper?86:88;p.x+=dx/d*Math.min(d,speed*dt);p.y+=dy/d*Math.min(d,speed*dt)}});
 // Possession and dribbling: the closest player nudges the ball ahead.
 let closest=null,cd=34;playerObjs.forEach(p=>{const d=Math.hypot(p.x-ball.x,p.y-ball.y);if(d<cd){closest=p;cd=d}});if(closest&&Math.hypot(ball.vx,ball.vy)<270){if(closest.team===0){const lead=closest.idx===selected?18:12;ball.x+=(closest.x+lead-ball.x)*Math.min(1,dt*11);ball.y+=(closest.y-ball.y)*Math.min(1,dt*11);ball.vx*=.78;ball.vy*=.78}else{ball.vx=-125;ball.vy+=(300-ball.y)*dt*1.1}}
 ball.x+=ball.vx*dt;ball.y+=ball.vy*dt;ball.vx*=Math.pow(.985,dt*60);ball.vy*=Math.pow(.985,dt*60);if(ball.y<48||ball.y>552){ball.y=Math.max(48,Math.min(552,ball.y));ball.vy*=-.7}if(ball.x<35){if(ball.y>245&&ball.y<355)score(1);else{ball.x=42;ball.vx=Math.abs(ball.vx)*.6}}if(ball.x>965){if(ball.y>245&&ball.y<355)score(0);else{ball.x=958;ball.vx=-Math.abs(ball.vx)*.6}}
 // Keep rival clearances and opportunistic attacks lively.
 if(closest&&closest.team===1&&ball.x<800&&Math.random()<dt*.75){ball.vx=260;ball.vy=(300-ball.y)*.25+(Math.random()-.5)*150}
 draw();requestAnimationFrame(loop)}
document.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(k))e.preventDefault();keys[k===' '?'space':k]=true;if((k===' '||k==='space')&&!e.repeat)doAction('shoot');if(k==='j'&&!e.repeat)doAction('pass')});document.addEventListener('keyup',e=>{const k=e.key.toLowerCase();keys[k===' '?'space':k]=false});
document.querySelectorAll('[data-key]').forEach(btn=>{const k=btn.dataset.key.toLowerCase();btn.addEventListener('pointerdown',e=>{e.preventDefault();keys[k]=true;btn.setPointerCapture(e.pointerId)});['pointerup','pointercancel','lostpointercapture'].forEach(ev=>btn.addEventListener(ev,()=>keys[k]=false))});document.querySelectorAll('[data-action]').forEach(btn=>btn.addEventListener('pointerdown',e=>{e.preventDefault();doAction(btn.dataset.action)}));
$('playBtn').onclick=()=>{home=0;away=0;$('homeScore').textContent='0';$('awayScore').textContent='0';kickoff()};$('sidePlay').onclick=()=>{if(!playing){home=0;away=0;$('homeScore').textContent='0';$('awayScore').textContent='0';$('modalKicker').textContent='EL CLÁSICO TE ESPERA';$('modalTitle').innerHTML='Arma tu<br>equipo de leyendas';$('modalText').textContent='Elige a tu protagonista y salta a la cancha. El estadio está lleno, la gloria te espera.';$('playBtn').textContent='JUGAR PARTIDO  →';$('overlay').classList.remove('hidden')}};
resize();
</script>
</body>
</html>

